1	package org.tasktelemetry;
2	
3	import java.time.Clock;
4	import java.time.Duration;
5	import java.util.Objects;
6	
7	import org.tasktelemetry.event.TaskEvent;
8	import org.tasktelemetry.event.TaskEventType;
9	import org.tasktelemetry.event.TaskExecutionDescriptor;
10	import org.tasktelemetry.event.TaskFailure;
11	import org.tasktelemetry.heartbeat.HeartbeatHandle;
12	import org.tasktelemetry.heartbeat.HeartbeatScheduler;
13	import org.tasktelemetry.transport.TaskTransport;
14	
15	/**
16	 * Emits telemetry events for a single task execution.
17	 *
18	 * <p>A reporter is bound to one {@link TaskExecutionDescriptor}. It emits
19	 * {@link TaskEventType#STARTED} on creation and publishes every subsequent event
20	 * through the configured {@link TaskTransport}, generating {@code eventId},
21	 * {@code timestamp} (from the injected {@link Clock}) and a monotonic
22	 * {@code sequenceNumber}.
23	 *
24	 * <p>When a {@link HeartbeatScheduler} and an interval are supplied, the reporter
25	 * emits a {@link TaskEventType#HEARTBEAT} on every tick during which no other
26	 * event was emitted: normal events count as liveness signals and suppress the
27	 * next heartbeat. The heartbeat starts after {@code STARTED} and stops as soon as
28	 * a terminal event is emitted or the reporter is closed.
29	 *
30	 * <p>The reporter implements {@link AutoCloseable} and is meant to be used with
31	 * try-with-resources. If it is closed without a terminal event having been
32	 * emitted, it applies its {@link CloseBehavior} (by default it emits
33	 * {@link TaskEventType#CANCELLED}).
34	 *
35	 * <p>Once a terminal event ({@code COMPLETED}, {@code FAILED} or
36	 * {@code CANCELLED}) has been emitted, any further emission throws
37	 * {@link IllegalStateException}; {@link #close()} becomes a no-op.
38	 *
39	 * <p>Instances are safe for concurrent use: event emission is serialized so that
40	 * sequence numbers and lifecycle state stay consistent, including against the
41	 * heartbeat thread.
42	 */
43	public final class TaskReporter implements AutoCloseable {
44	
45	    /**
46	     * Action taken when the reporter is closed without a terminal event.
47	     */
48	    public enum CloseBehavior {
49	        CANCELLED,
50	        FAILED,
51	        IGNORE
52	    }
53	
54	    private static final String CLOSE_WITHOUT_TERMINAL_MESSAGE =
55	            "Reporter closed without a terminal event";
56	
57	    private final TaskExecutionDescriptor descriptor;
58	    private final TaskTransport transport;
59	    private final Clock clock;
60	    private final CloseBehavior closeBehavior;
61	    private final TaskTelemetryErrorHandler errorHandler;
62	    private final boolean includeStackTrace;
63	
64	    private long nextSequenceNumber;
65	    private boolean terminalEmitted;
66	    private boolean closed;
67	    private boolean emittedSinceLastTick;
68	    private HeartbeatHandle heartbeatHandle;
69	
70	    /**
71	     * Creates a reporter with the default settings (see
72	     * {@link TaskReporterSettings#defaults()}).
73	     *
74	     * @param descriptor identity of the execution, required
75	     * @param transport  transport used to publish events, required
76	     */
77	    public TaskReporter(TaskExecutionDescriptor descriptor, TaskTransport transport) {
78	        this(descriptor, transport, TaskReporterSettings.defaults());
79	    }
80	
81	    /**
82	     * Creates a reporter, emits {@link TaskEventType#STARTED} and, when the
83	     * settings supply a scheduler and interval, starts the automatic heartbeat.
84	     *
85	     * @param descriptor identity of the execution, required
86	     * @param transport  transport used to publish events, required
87	     * @param settings   reporter configuration, required
88	     */
89	    public TaskReporter(
90	            TaskExecutionDescriptor descriptor,
91	            TaskTransport transport,
92	            TaskReporterSettings settings) {
93	
94	        Objects.requireNonNull(settings, "settings must not be null");
95	        this.descriptor = Objects.requireNonNull(descriptor, "descriptor must not be null");
96	        this.transport = Objects.requireNonNull(transport, "transport must not be null");
97	        this.clock = settings.clock();
98	        this.closeBehavior = settings.closeBehavior();
99	        this.errorHandler = settings.errorHandler();
100	        this.includeStackTrace = settings.includeStackTrace();
101	
102	        emit(TaskEventType.STARTED, null, null, null);
103	        this.heartbeatHandle = startHeartbeat(settings.heartbeatScheduler(), settings.heartbeatInterval());
104	    }
105	
106	    /**
107	     * Returns the identity of the execution this reporter is bound to.
108	     *
109	     * @return the execution descriptor
110	     */
111	    public TaskExecutionDescriptor descriptor() {
112	        return descriptor;
113	    }
114	
115	    /**
116	     * Emits a progress event.
117	     *
118	     * @param percentage completion percentage between {@code 0} and {@code 100}
119	     * @param message    optional message, may be {@code null}
120	     */
121	    public synchronized void progress(int percentage, String message) {
122	        ensureActive();
123	        emit(TaskEventType.PROGRESS, message, percentage, null);
124	    }
125	
126	    /**
127	     * Emits an informational event.
128	     *
129	     * @param message the message, may be {@code null}
130	     */
131	    public synchronized void info(String message) {
132	        ensureActive();
133	        emit(TaskEventType.INFO, message, null, null);
134	    }
135	
136	    /**
137	     * Emits a warning event.
138	     *
139	     * @param message the message, may be {@code null}
140	     */
141	    public synchronized void warning(String message) {
142	        ensureActive();
143	        emit(TaskEventType.WARNING, message, null, null);
144	    }
145	
146	    /**
147	     * Emits a heartbeat event signalling that the execution is still alive.
148	     */
149	    public synchronized void heartbeat() {
150	        ensureActive();
151	        emit(TaskEventType.HEARTBEAT, null, null, null);
152	    }
153	
154	    /**
155	     * Emits a custom application event.
156	     *
157	     * @param message optional message, may be {@code null}
158	     * @param payload optional payload, may be {@code null}
159	     */
160	    public synchronized void custom(String message, Object payload) {
161	        ensureActive();
162	        emit(TaskEventType.CUSTOM, message, null, payload);
163	    }
164	
165	    /**
166	     * Emits a terminal success event.
167	     *
168	     * @param message optional message, may be {@code null}
169	     */
170	    public synchronized void completed(String message) {
171	        emitTerminal(TaskEventType.COMPLETED, message, null);
172	    }
173	
174	    /**
175	     * Emits a terminal failure event carrying the error.
176	     *
177	     * @param error the cause of the failure, required
178	     */
179	    public synchronized void failed(Throwable error) {
180	        Objects.requireNonNull(error, "error must not be null");
181	
182	        TaskFailure failure = TaskFailure.from(error, includeStackTrace);
183	        emitTerminal(TaskEventType.FAILED, error.toString(), failure);
184	    }
185	
186	    /**
187	     * Emits a terminal cancellation event.
188	     *
189	     * @param message optional message, may be {@code null}
190	     */
191	    public synchronized void cancelled(String message) {
192	        emitTerminal(TaskEventType.CANCELLED, message, null);
193	    }
194	
195	    @Override
196	    public synchronized void close() {
197	        if (terminalEmitted || closed) {
198	            closed = true;
199	            stopHeartbeat();
200	            return;
201	        }
202	
203	        emitCloseEvent();
204	        closed = true;
205	        stopHeartbeat();
206	    }
207	
208	    private void onHeartbeatTick() {
209	        synchronized (this) {
210	            if (closed || terminalEmitted) {
211	                return;
212	            }
213	            if (emittedSinceLastTick) {
214	                emittedSinceLastTick = false;
215	                return;
216	            }
217	            emit(TaskEventType.HEARTBEAT, null, null, null);
218	        }
219	    }
220	
221	    private HeartbeatHandle startHeartbeat(HeartbeatScheduler scheduler, Duration interval) {
222	        if (scheduler == null && interval == null) {
223	            return null;
224	        }
225	
226	        Objects.requireNonNull(scheduler, "heartbeatScheduler must not be null");
227	        Objects.requireNonNull(interval, "heartbeatInterval must not be null");
228	        requirePositive(interval);
229	        return scheduler.schedule(this::onHeartbeatTick, interval);
230	    }
231	
232	    private void emitCloseEvent() {
233	        if (closeBehavior == CloseBehavior.IGNORE) {
234	            return;
235	        }
236	
237	        emit(closeTerminalType(), CLOSE_WITHOUT_TERMINAL_MESSAGE, null, null);
238	        terminalEmitted = true;
239	    }
240	
241	    private TaskEventType closeTerminalType() {
242	        return switch (closeBehavior) {
243	            case CANCELLED -> TaskEventType.CANCELLED;
244	            case FAILED -> TaskEventType.FAILED;
245	            case IGNORE -> throw new IllegalStateException("IGNORE has no terminal type");
246	        };
247	    }
248	
249	    private void emitTerminal(TaskEventType type, String message, Object payload) {
250	        ensureActive();
251	        emit(type, message, null, payload);
252	        terminalEmitted = true;
253	        stopHeartbeat();
254	    }
255	
256	    private void emit(TaskEventType type, String message, Integer progress, Object payload) {
257	        long sequenceNumber = nextSequenceNumber++;
258	
259	        TaskEvent event = TaskEvent.builder()
260	                .eventId(descriptor.executionId() + "-" + sequenceNumber)
261	                .taskName(descriptor.taskName())
262	                .executionId(descriptor.executionId())
263	                .correlationKey(descriptor.correlationKey())
264	                .type(type)
265	                .timestamp(clock.instant())
266	                .sequenceNumber(sequenceNumber)
267	                .message(message)
268	                .progress(progress)
269	                .payload(payload)
270	                .build();
271	
272	        publish(event);
273	
274	        if (type != TaskEventType.HEARTBEAT) {
275	            emittedSinceLastTick = true;
276	        }
277	    }
278	
279	    private void publish(TaskEvent event) {
280	        try {
281	            transport.publish(event);
282	        } catch (RuntimeException error) {
283	            errorHandler.onPublishFailure(event, error);
284	        }
285	    }
286	
287	    private void stopHeartbeat() {
288	        if (heartbeatHandle != null) {
289	            heartbeatHandle.cancel();
290	            heartbeatHandle = null;
291	        }
292	    }
293	
294	    private void ensureActive() {
295	        if (terminalEmitted) {
296	            throw new IllegalStateException(
297	                    "Execution " + descriptor.executionId()
298	                            + " already reached a terminal event");
299	        }
300	        if (closed) {
301	            throw new IllegalStateException(
302	                    "Reporter for execution " + descriptor.executionId() + " is already closed");
303	        }
304	    }
305	
306	    private static void requirePositive(Duration interval) {
307	        if (interval.isZero() || interval.isNegative()) {
308	            throw new IllegalArgumentException(
309	                    "heartbeatInterval must be positive: " + interval);
310	        }
311	    }
312	}
