21	/**
22	 * {@link TaskTransport} for the producer (task) side of the 2-actor cross-process topology.
23	 *
24	 * <p>The server binds a TCP port on construction and listens for incoming client
25	 * connections from {@link SocketClientTaskTransport} instances. When {@link #publish}
26	 * is called, the event is serialized to a text line and written to <em>every</em>
27	 * currently-connected client (best-effort broadcast). Events published when no
28	 * client is connected are silently discarded — there is no buffering or replay.
29	 *
30	 * <h2>Topology role</h2>
31	 * In the 2-actor model the <em>task is the server</em> and clients are consumers.
32	 * The server emits blindly: it does not know how many clients are connected, does
33	 * not wait for acknowledgements, and does not read from client sockets.
34	 *
35	 * <h2>Binding</h2>
36	 * Pass {@code port = 0} to let the OS assign an ephemeral port; read the actual
37	 * bound port back via {@link #port()}. This is particularly useful in tests.
38	 *
39	 * <h2>Accept loop</h2>
40	 * A daemon thread ({@code task-telemetry-crossprocess-server-accept-N}) accepts new
41	 * client connections and adds them to the internal broadcast list. A client that
42	 * disconnects is detected on the next write attempt and silently removed.
43	 *
44	 * <h2>Local in-JVM listeners</h2>
45	 * {@link #subscribe} / {@link #unsubscribe} register in-JVM listeners that receive
46	 * events exactly like a remote client, without going through the socket.
47	 *
48	 * <h2>Limitations (v1)</h2>
49	 * <ul>
50	 *   <li>Events published before a client connects are not delivered (no replay).</li>
51	 *   <li>The {@code payload} field is not transmitted; it will be {@code null}
52	 *       on the receiving side.</li>
53	 *   <li>Clients are consumer-only; the server does not read from them.</li>
54	 * </ul>
55	 *
56	 * <h2>Thread safety</h2>
57	 * All public methods are safe for concurrent use.
58	 */
59	public final class SocketServerTaskTransport implements TaskTransport, AutoCloseable {
60	
61	    private static final Logger LOGGER = Logger.getLogger(SocketServerTaskTransport.class.getName());
62	    private static final String ACCEPT_THREAD_PREFIX = "task-telemetry-crossprocess-server-accept-";
63	
64	    private static final AtomicInteger SERVER_COUNTER = new AtomicInteger(1);
65	
66	    private final ServerSocket serverSocket;
67	    private final TaskEventSerializer serializer;
68	    private final CopyOnWriteArrayList<ClientWriter> clientWriters = new CopyOnWriteArrayList<>();
69	    private final CopyOnWriteArrayList<TaskListener> localListeners = new CopyOnWriteArrayList<>();
70	    private final String serverName;
71	
72	    /**
73	     * Binds to the given port and starts accepting client connections, using the
74	     * default {@link TextTaskEventSerializer}.
75	     *
76	     * @param port the TCP port to bind; {@code 0} for an OS-assigned ephemeral port
77	     * @throws IOException if the server socket cannot be created
78	     */
79	    public SocketServerTaskTransport(int port) throws IOException {
80	        this(port, new TextTaskEventSerializer());
81	    }
82	
83	    /**
84	     * Binds to the given port and starts accepting client connections, using the
85	     * provided serializer.
86	     *
87	     * @param port       the TCP port to bind; {@code 0} for an OS-assigned ephemeral port
88	     * @param serializer the serializer to use for encoding events to the wire
89	     * @throws IOException if the server socket cannot be created
90	     */
91	    public SocketServerTaskTransport(int port, TaskEventSerializer serializer) throws IOException {
92	        Objects.requireNonNull(serializer, "serializer must not be null");
93	
94	        this.serializer = serializer;
95	        this.serverName = String.valueOf(SERVER_COUNTER.getAndIncrement());
96	        this.serverSocket = new ServerSocket(port);
97	        startAcceptLoop();
98	    }
99	
100	    /**
101	     * Returns the actual TCP port this server is listening on.
102	     *
103	     * <p>Useful when the server was created with {@code port = 0} (ephemeral port).
104	     *
105	     * @return the bound port
106	     */
107	    public int port() {
108	        return serverSocket.getLocalPort();
109	    }
110	
111	    /**
112	     * Serializes the event and writes it to all currently-connected clients.
113	     *
114	     * <p>Delivery is best-effort: if a client socket is broken, that client is
115	     * dropped and the remaining clients are not affected. If no client is connected
116	     * the event is discarded. Local in-JVM listeners registered via {@link #subscribe}
117	     * receive the event regardless of connected clients.
118	     */
119	    @Override
120	    public void publish(TaskEvent event) {
121	        Objects.requireNonNull(event, "event must not be null");
122	
123	        String line = serializer.serialize(event);
124	        broadcastToClients(line);
125	        dispatchToLocalListeners(event);
126	    }
127	
128	    /**
