import java.util.logging.Level;
import java.util.logging.Logger;

import org.tasktelemetry.event.TaskEvent;
import org.tasktelemetry.listener.TaskListener;
import org.tasktelemetry.transport.TaskTransport;

/**
 * {@link TaskTransport} for the producer (task) side of the 2-actor cross-process topology.
 *
 * <p>The server binds a TCP port on construction and listens for incoming client
 * connections from {@link SocketClientTaskTransport} instances. When {@link #publish}
 * is called, the event is serialized to a text line and written to <em>every</em>
 * currently-connected client (best-effort broadcast). Events published when no
 * client is connected are silently discarded — there is no buffering or replay.
 *
 * <h2>Topology role</h2>
 * In the 2-actor model the <em>task is the server</em> and clients are consumers.
 * The server emits blindly: it does not know how many clients are connected, does
 * not wait for acknowledgements, and does not read from client sockets.
 *
 * <h2>Binding</h2>
 * Pass {@code port = 0} to let the OS assign an ephemeral port; read the actual
 * bound port back via {@link #port()}. This is particularly useful in tests.
 *
 * <h2>Accept loop</h2>
 * A daemon thread ({@code task-telemetry-crossprocess-server-accept-N}) accepts new
 * client connections and adds them to the internal broadcast list. A client that
 * disconnects is detected on the next write attempt and silently removed.
 *
 * <h2>Local in-JVM listeners</h2>
 * {@link #subscribe} / {@link #unsubscribe} register in-JVM listeners that receive
 * events exactly like a remote client, without going through the socket.
 *
 * <h2>Limitations (v1)</h2>
 * <ul>
 *   <li>Events published before a client connects are not delivered (no replay).</li>
 *   <li>The {@code payload} field is not transmitted; it will be {@code null}
 *       on the receiving side.</li>
 *   <li>Clients are consumer-only; the server does not read from them.</li>
 * </ul>
 *
 * <h2>Thread safety</h2>
 * All public methods are safe for concurrent use.
 */
public final class SocketServerTaskTransport implements TaskTransport, AutoCloseable {

    private static final Logger LOGGER = Logger.getLogger(SocketServerTaskTransport.class.getName());
    private static final String ACCEPT_THREAD_PREFIX = "task-telemetry-crossprocess-server-accept-";

    private static final AtomicInteger SERVER_COUNTER = new AtomicInteger(1);

    private final ServerSocket serverSocket;
    private final TaskEventSerializer serializer;
    private final CopyOnWriteArrayList<ClientWriter> clientWriters = new CopyOnWriteArrayList<>();
    private final CopyOnWriteArrayList<TaskListener> localListeners = new CopyOnWriteArrayList<>();
    private final String serverName;

    /**
     * Binds to the given port and starts accepting client connections, using the
     * default {@link TextTaskEventSerializer}.
     *
     * @param port the TCP port to bind; {@code 0} for an OS-assigned ephemeral port
     * @throws IOException if the server socket cannot be created
     */
    public SocketServerTaskTransport(int port) throws IOException {
        this(port, new TextTaskEventSerializer());
    }

    /**
     * Binds to the given port and starts accepting client connections, using the
     * provided serializer.
     *
     * @param port       the TCP port to bind; {@code 0} for an OS-assigned ephemeral port
     * @param serializer the serializer to use for encoding events to the wire
     * @throws IOException if the server socket cannot be created
     */
    public SocketServerTaskTransport(int port, TaskEventSerializer serializer) throws IOException {
        Objects.requireNonNull(serializer, "serializer must not be null");

        this.serializer = serializer;
        this.serverName = String.valueOf(SERVER_COUNTER.getAndIncrement());
        this.serverSocket = new ServerSocket(port);
        startAcceptLoop();
    }

    /**
     * Returns the actual TCP port this server is listening on.
     *
     * <p>Useful when the server was created with {@code port = 0} (ephemeral port).
     *
     * @return the bound port
     */
    public int port() {
        return serverSocket.getLocalPort();
    }

    /**
     * Serializes the event and writes it to all currently-connected clients.
     *
     * <p>Delivery is best-effort: if a client socket is broken, that client is
     * dropped and the remaining clients are not affected. If no client is connected
     * the event is discarded. Local in-JVM listeners registered via {@link #subscribe}
     * receive the event regardless of connected clients.
     */
    @Override
    public void publish(TaskEvent event) {
        Objects.requireNonNull(event, "event must not be null");

        String line = serializer.serialize(event);
        broadcastToClients(line);
        dispatchToLocalListeners(event);
    }

    /**
     * Registers a local in-JVM listener.
     *
     * @param listener the listener to register, never {@code null}
     */
    @Override
    public void subscribe(TaskListener listener) {
        Objects.requireNonNull(listener, "listener must not be null");
        localListeners.add(listener);
    }

    /**
     * Removes a local in-JVM listener.
     *
     * @param listener the listener to remove, never {@code null}
     */
    @Override
    public void unsubscribe(TaskListener listener) {
        Objects.requireNonNull(listener, "listener must not be null");
        localListeners.remove(listener);
    }

    /**
     * Stops the accept loop, closes the server socket, and closes all client connections.
     */
    @Override
    public void close() {
        try {
            serverSocket.close();
        } catch (IOException ex) {
            LOGGER.log(Level.WARNING,
                    "task-telemetry - server " + serverName + ": error closing server socket", ex);
        }

        for (ClientWriter writer : clientWriters) {
            writer.close();
        }
        clientWriters.clear();
    }

    // --- accept loop ---

    private void startAcceptLoop() {
        Thread acceptThread = new Thread(this::acceptLoop,
                ACCEPT_THREAD_PREFIX + serverName);
        acceptThread.setDaemon(true);
        acceptThread.start();
    }

    private void acceptLoop() {
        while (!serverSocket.isClosed()) {
            try {
                Socket clientSocket = serverSocket.accept();
                ClientWriter writer = new ClientWriter(clientSocket);
                clientWriters.add(writer);
            } catch (SocketException ex) {
                // Normal shutdown: serverSocket.close() triggers this.
                break;
            } catch (IOException ex) {
                LOGGER.log(Level.WARNING,
                        "task-telemetry - server " + serverName + ": accept error", ex);
            }
        }
    }

    // --- broadcast ---

    private void broadcastToClients(String line) {
        for (ClientWriter writer : clientWriters) {
            writer.send(line);
        }
    }

    void removeClient(ClientWriter writer) {
        clientWriters.remove(writer);
    }

    // --- local listener dispatch ---

    private void dispatchToLocalListeners(TaskEvent event) {
        List<TaskListener> snapshot = List.copyOf(localListeners);
        for (TaskListener listener : snapshot) {
            dispatchToListener(listener, event);
        }
    }

    private void dispatchToListener(TaskListener listener, TaskEvent event) {
        try {
            listener.onEvent(event);
        } catch (Exception ex) {
            LOGGER.log(Level.WARNING,
                    "task-telemetry - SocketServerTaskTransport: listener threw an exception", ex);
        }
    }

    // --- per-connection writer ---

    /**
     * Wraps a single accepted client socket for write-only access.
     * The server never reads from clients; it only writes serialized event lines.
     */
    final class ClientWriter {

        private final Socket socket;
        private final BufferedWriter writer;

        ClientWriter(Socket socket) throws IOException {
            this.socket = socket;
            this.writer = new BufferedWriter(
                    new OutputStreamWriter(socket.getOutputStream(), StandardCharsets.UTF_8));
        }

        synchronized void send(String line) {
            try {
                writer.write(line);
                writer.newLine();
                writer.flush();
            } catch (IOException ex) {
                // The client disconnected — drop it so other clients are not affected.
                LOGGER.log(Level.FINE,
                        "task-telemetry - server " + serverName
                                + ": client disconnected, dropping connection", ex);
                removeClient(this);
                close();
            }
        }

        void close() {
            try {
                socket.close();
            } catch (IOException ex) {
                LOGGER.log(Level.FINE,
                        "task-telemetry - server " + serverName
                                + ": error closing client socket", ex);
            }
        }
    }
}

package org.tasktelemetry.transport.crossprocess;

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.net.Socket;
import java.net.SocketException;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Level;
import java.util.logging.Logger;

import org.tasktelemetry.event.TaskEvent;
import org.tasktelemetry.listener.TaskListener;
import org.tasktelemetry.transport.TaskTransport;

/**
 * {@link TaskTransport} for the consumer side of the 2-actor cross-process topology.
 *
 * <p>This client connects to a {@link SocketServerTaskTransport} (the task / producer
 * side) over a localhost TCP socket. From the moment the connection is established,
 * any event published by the server is serialized to a text line and pushed to this
 * client, which deserializes it and dispatches it to all locally-registered listeners.
 *
 * <h2>Topology role</h2>
 * In the 2-actor model the <em>task is the server</em> and the <em>client is the
 * consumer</em>. A client can call {@link #publish} (the bytes are written to the
 * socket), but in this topology the server does not read from clients; the method
 * exists only to satisfy the {@link TaskTransport} contract. Typical consumers
 * should use {@link #subscribe} only.
 *
 * <h2>Connection</h2>
 * The socket is opened during construction. If the server is not reachable, a
 * {@link TaskUnreachableException} is thrown immediately.
 *
 * <h2>Reader thread</h2>
 * A single daemon thread ({@code task-telemetry-crossprocess-client-N}) reads lines
 * sent by the server, deserializes each one and dispatches it to all locally-subscribed
 * listeners. A listener that throws is isolated; it does not stop the reader loop.
 *
 * <h2>Limitations (v1)</h2>
 * <ul>
 *   <li>No auto-reconnect: if the server closes or the connection is lost, this
 *       client does not reconnect automatically.</li>
 *   <li>The {@code payload} field is not transmitted; it will be {@code null}
 *       on the receiving side.</li>
 *   <li>Events published before this client connected are not replayed.</li>
 * </ul>
 *
 * <h2>Thread safety</h2>
 * All public methods are safe for concurrent use.
 */
public final class SocketClientTaskTransport implements TaskTransport, AutoCloseable {

    private static final Logger LOGGER = Logger.getLogger(SocketClientTaskTransport.class.getName());
    private static final String THREAD_PREFIX = "task-telemetry-crossprocess-client-";

    private static final AtomicInteger CLIENT_COUNTER = new AtomicInteger(1);

    private final Socket socket;
    private final BufferedWriter writer;
    private final TaskEventSerializer serializer;
    private final CopyOnWriteArrayList<TaskListener> listeners = new CopyOnWriteArrayList<>();

    /**
     * Connects to the task server at the given host and port using the default
     * {@link TextTaskEventSerializer}.
     *
     * @param host the server host name or IP address
     * @param port the server port
     * @throws TaskUnreachableException if the connection cannot be established
     */
    public SocketClientTaskTransport(String host, int port) {
        this(host, port, new TextTaskEventSerializer());
    }

    /**
     * Connects to the task server at the given host and port using the provided serializer.
     *
     * @param host       the server host name or IP address
     * @param port       the server port
     * @param serializer the serializer to use for decoding incoming events
     * @throws TaskUnreachableException if the connection cannot be established
     */
    public SocketClientTaskTransport(String host, int port, TaskEventSerializer serializer) {
        Objects.requireNonNull(host, "host must not be null");
        Objects.requireNonNull(serializer, "serializer must not be null");

        this.serializer = serializer;
        this.socket = connect(host, port);
        this.writer = openWriter(this.socket);
        startReaderThread();
    }

    /**
     * Writes a serialized event to the socket.
     *
     * <p><b>Note:</b> in the 2-actor topology the server ({@link SocketServerTaskTransport})
     * does not read from clients. This method writes the bytes to the socket but they will
     * not be processed by the server. It exists only to satisfy the {@link TaskTransport}
     * contract. Typical consumers should not call this method.
     */
    @Override
    public void publish(TaskEvent event) {
        Objects.requireNonNull(event, "event must not be null");

        String line = serializer.serialize(event);
        sendLine(line);
    }

    @Override
    public void subscribe(TaskListener listener) {
        Objects.requireNonNull(listener, "listener must not be null");
        listeners.add(listener);
    }

    @Override
    public void unsubscribe(TaskListener listener) {
        Objects.requireNonNull(listener, "listener must not be null");
        listeners.remove(listener);
    }

    /**
     * Stops the reader thread and closes the socket connection to the server.
     */
    @Override
    public void close() {
        try {
            socket.close();
        } catch (IOException ex) {
            LOGGER.log(Level.WARNING,
                    "task-telemetry - SocketClientTaskTransport: error closing socket", ex);
        }
    }

    // --- setup helpers ---

    private static Socket connect(String host, int port) {
        try {
            return new Socket(host, port);
        } catch (IOException ex) {
            throw new TaskUnreachableException(
                    "task-telemetry - SocketClientTaskTransport: cannot reach task server at "
                            + host + ":" + port, ex);
        }
    }

    private static BufferedWriter openWriter(Socket socket) {
        try {
            return new BufferedWriter(
                    new OutputStreamWriter(socket.getOutputStream(), StandardCharsets.UTF_8));
        } catch (IOException ex) {
            throw new IllegalStateException(
                    "task-telemetry - SocketClientTaskTransport: cannot open output stream", ex);
        }
    }

    private void startReaderThread() {
        Thread readerThread = new Thread(this::readLoop,
                THREAD_PREFIX + CLIENT_COUNTER.getAndIncrement());
        readerThread.setDaemon(true);
        readerThread.start();
    }

    // --- I/O ---

    private synchronized void sendLine(String line) {
        try {
            writer.write(line);
            writer.newLine();
            writer.flush();
        } catch (IOException ex) {
            // Best-effort: log the failure but do not crash the caller.
            LOGGER.log(Level.WARNING,
                    "task-telemetry - SocketClientTaskTransport: failed to write to socket", ex);
        }
    }

    private void readLoop() {
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(socket.getInputStream(), StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                dispatchLine(line);
            }
        } catch (SocketException ex) {
            // Normal: socket was closed by close() or the server shut down.
        } catch (IOException ex) {
            LOGGER.log(Level.WARNING,
                    "task-telemetry - SocketClientTaskTransport: read error in reader thread", ex);
        }
    }

    private void dispatchLine(String line) {
        TaskEvent event;
        try {
            event = serializer.deserialize(line);
        } catch (IllegalArgumentException ex) {
            LOGGER.log(Level.WARNING,
                    "task-telemetry - SocketClientTaskTransport: skipping malformed line: ["
                            + line + "]", ex);
            return;
        }

        List<TaskListener> snapshot = List.copyOf(listeners);
        for (TaskListener listener : snapshot) {
            dispatchToListener(listener, event);
        }
    }

    private void dispatchToListener(TaskListener listener, TaskEvent event) {
        try {
            listener.onEvent(event);
        } catch (Exception ex) {
            // Isolate listener failures so one bad listener cannot kill the reader loop.
            LOGGER.log(Level.WARNING,
                    "task-telemetry - SocketClientTaskTransport: listener threw an exception", ex);
        }
    }
}

package org.tasktelemetry.watch;

import java.time.Clock;
import java.time.Duration;
import java.util.Objects;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.IntConsumer;

import org.tasktelemetry.event.TaskEvent;
import org.tasktelemetry.event.TaskEventType;
import org.tasktelemetry.listener.ListenerHandle;
import org.tasktelemetry.listener.ListenerRegistration;
import org.tasktelemetry.listener.TaskAwaitTimeoutException;
import org.tasktelemetry.monitor.TaskExecutionStatus;
import org.tasktelemetry.monitor.TaskHeartbeatMonitor;
import org.tasktelemetry.transport.TaskTransport;

/**
 * High-level helper for consumers that want to follow a single task without
 * dealing with listeners, monitors, latches or execution ids.
 *
 * <p>Typical use: wait for a task to be running, react to its progress, and block
 * until it finishes. Liveness is handled internally: if the task stops emitting
 * (its heart stops), {@link #awaitCompletion()} returns
 * {@link TaskExecutionStatus#LOST} instead of blocking forever, so the consumer
 * never has to check heartbeats itself.
 *
 * <pre>{@code
 * try (TaskWatcher watcher = new TaskWatcher(bus, "FILE_UPLOAD")) {
 *     watcher.onProgress(percent -> progressBar.setValue(percent));
 *     if (!watcher.awaitStart(Duration.ofSeconds(5))) {
 *         return; // no upload running
 *     }
 *     TaskExecutionStatus status = watcher.awaitCompletion();
 * }
 * }</pre>
 */
public final class TaskWatcher implements AutoCloseable {

    private static final Duration DEFAULT_STALE_AFTER = Duration.ofSeconds(5);
    private static final Duration DEFAULT_LOST_AFTER = Duration.ofSeconds(15);
    private static final Duration POLL_INTERVAL = Duration.ofMillis(100);

    private final TaskTransport transport;
    private final String taskName;
    private final TaskHeartbeatMonitor monitor;
    private final CountDownLatch finished = new CountDownLatch(1);
    private final AtomicReference<String> executionId = new AtomicReference<>();

    private IntConsumer progressCallback = percent -> {
    };
    private Runnable heartbeatCallback = () -> {
    };
    private ListenerHandle handle;

    public TaskWatcher(TaskTransport transport, String taskName) {
        this(transport, taskName, DEFAULT_STALE_AFTER, DEFAULT_LOST_AFTER);
    }

    public TaskWatcher(TaskTransport transport, String taskName, Duration staleAfter, Duration lostAfter) {
        this.transport = Objects.requireNonNull(transport, "transport must not be null");
        this.taskName = Objects.requireNonNull(taskName, "taskName must not be null");
        this.monitor = new TaskHeartbeatMonitor(Clock.systemUTC(), staleAfter, lostAfter);
    }

    /**
     * Registers a callback invoked with the percentage of each progress event.
     *
     * @param progressCallback the callback, required
     * @return this watcher
     */
    public TaskWatcher onProgress(IntConsumer progressCallback) {
        this.progressCallback =
                Objects.requireNonNull(progressCallback, "progressCallback must not be null");
        return this;
    }

    /**
     * Registers a callback invoked on every {@code HEARTBEAT} event, kept separate
     * from {@link #onProgress}. The heartbeat carries no payload of its own; it
     * only signals that the task is still alive.
     *
     * @param heartbeatCallback the callback, required
     * @return this watcher
     */
    public TaskWatcher onHeartbeat(Runnable heartbeatCallback) {
        this.heartbeatCallback =
                Objects.requireNonNull(heartbeatCallback, "heartbeatCallback must not be null");
        return this;
    }

    /**
     * Subscribes and blocks until the task emits its first event or the timeout
     * elapses.
     *
     * @param timeout maximum time to wait for the task to show up
     * @return {@code true} if the task is running, {@code false} if it did not
     *         appear within the timeout
     */
    public boolean awaitStart(Duration timeout) {
        try {
            this.handle = new ListenerRegistration(transport)
                    .taskName(taskName)
                    .onEvent(this::onEvent)
                    .awaitStart(timeout);
            return true;
        } catch (TaskAwaitTimeoutException notRunning) {
            return false;
        }
    }

    /**
     * Blocks until the task reaches a terminal event or is considered lost.
     *
     * @return the final status: {@code COMPLETED}, {@code FAILED}, {@code CANCELLED}
     *         or {@code LOST}
     */
    public TaskExecutionStatus awaitCompletion() {
        String execId = executionId.get();
        if (execId == null) {
            throw new IllegalStateException("awaitStart must succeed before awaitCompletion");
        }

        while (true) {
            if (awaitFinished()) {
                return monitor.statusOf(execId);
            }
            if (monitor.statusOf(execId) == TaskExecutionStatus.LOST) {
                return TaskExecutionStatus.LOST;
            }
        }
    }

    @Override
    public void close() {
        if (handle != null) {
            handle.stop();
        }
    }

    private void onEvent(TaskEvent event) {
        executionId.compareAndSet(null, event.executionId());
        monitor.onEvent(event);

        if (event.type() == TaskEventType.HEARTBEAT) {
            heartbeatCallback.run();
        }

        Integer progress = event.progress();
        if (progress != null) {
            progressCallback.accept(progress);
        }
        if (event.type().isTerminal()) {
            finished.countDown();
        }
    }

    private boolean awaitFinished() {
        try {
            return finished.await(POLL_INTERVAL.toMillis(), TimeUnit.MILLISECONDS);
        } catch (InterruptedException interrupted) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException("Interrupted while awaiting task completion", interrupted);
        }
    }
}

